DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.configure_employee_clock_methods(uuid,text,text,time,time,integer[],integer,uuid,boolean,text[])'::regprocedure) INTO definition; definition:=replace(definition,'IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=_employee)', 'IF NOT (_methods && ARRAY[''account'',''pin'']) THEN RAISE EXCEPTION ''Choose account or PIN identification; voice is an additional clock method''; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=_employee)'); EXECUTE definition; END $$;